import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;

public class SolutionTest {
    public static void main(String[] args) {
        assertTrue(Solution.ownershipPercent(null).isEmpty(), "null input");
        assertTrue(Solution.ownershipPercent(new ArrayList<String>()).isEmpty(), "empty input");
        assertTrue(Solution.ownershipPercent(Arrays.asList(null, "", "  ")).isEmpty(), "invalid-only input");

        List<String> input = new ArrayList<String>(Arrays.asList(" Alice ", "Bob", null, "", "Alice", " alice ", "Bob", "Carol"));
        List<String> snapshot = new ArrayList<String>(input);
        final Map<String, Integer> result = Solution.ownershipPercent(input);
        assertEquals(Arrays.asList("Alice", "Bob", "alice", "Carol"), new ArrayList<String>(result.keySet()));
        assertEquals(Integer.valueOf(33), result.get("Alice"));
        assertEquals(Integer.valueOf(33), result.get("Bob"));
        assertEquals(Integer.valueOf(16), result.get("alice"));
        assertEquals(Integer.valueOf(16), result.get("Carol"));
        assertEquals(4, result.size());
        assertEquals(snapshot, input);

        expectUnsupported(new Runnable() {
            public void run() { result.put("New", 1); }
        });
        expectUnsupported(new Runnable() {
            public void run() { result.remove("Alice"); }
        });

        input.clear();
        input.add("Changed");
        assertEquals(Integer.valueOf(33), result.get("Alice"));
        assertEquals(4, result.size());

        Map<String, Integer> thirds = Solution.ownershipPercent(Arrays.asList("A", "B", "C"));
        assertEquals(Integer.valueOf(33), thirds.get("A"));
        assertEquals(Integer.valueOf(33), thirds.get("B"));
        assertEquals(Integer.valueOf(33), thirds.get("C"));
        Map<String, Integer> all = Solution.ownershipPercent(Arrays.asList(" X ", "X"));
        assertEquals(Integer.valueOf(100), all.get("X"));
    }

    private static void expectUnsupported(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void assertEquals(Object expected, Object actual) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError("expected " + expected + " but got " + actual);
        }
    }
}

